const equipmentMap: Record<string, EquipmentId> = { W: "arma", A: "armadura", R: "artefato" };

export const characters: Character[] = records.map((record) => {
  const [name, identity, category, alignment, team, powers, equipmentCode, weapons, armor, comics, overview, secret] = record;
  return {
    id: "m-" + name.toLocaleLowerCase("en-US").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, "-"),
    name,
    identity,
    universe: "marvel" as const,
    category,
    alignment,
    team,
    powers: powers.split("|"),
    equipment: equipmentCode === "N" ? [] : equipmentCode.split("").map((code) => equipmentMap[code]),
    weapons,
    armor,
    comics: comics.split("|"),
    overview,
    secret,
    image: officialArt[name],
  };
});

